function writePaperResultsText(r,outdir)
%WRITEPAPERRESULTSTEXT Generate paper prose and numerical table from this run.
s=r.Summary; mb=r.Controllers{2}; dd=r.Controllers{3};
droopIndex=find(startsWith(r.Methods,"Conventional droop"),1);
assert(~isempty(droopIndex),'DCMG:MissingDroopBaseline', ...
    'The generated report does not contain the conventional droop baseline.');
droop=r.Controllers{droopIndex};
fid=fopen(fullfile(outdir,'numerical_results.tex'),'w'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
put(fid,'% Generated by run_paper_results.m; do not edit numerical values manually.');
put(fid,'\subsubsection{Benchmark and implementation contract}');
put(fid,'We regenerate the six-DG, seven-line benchmark using the component values and initial condition retained in the original MATLAB implementation. The plant has ZI loads and continuously varying resistive line currents. All reported controllers act on the same plant and equilibrium. The equilibrium enforces the voltage, command, exported-current, and proportional-current-sharing constraints in \eqref{Eq:DGSpecs1}--\eqref{Eq:DGSpecs4}.');
put(fid,latexFormat('The common current-utilization fraction is $%.6f$; equilibrium voltages range from $%.4f$ to $%.4f$ V. The maximum equilibrium equation residual is $%.2e$.', ...
    r.PhysicalParameters.SteadyState.epsI,min(r.PhysicalParameters.SteadyState.V_ss), ...
    max(r.PhysicalParameters.SteadyState.V_ss),r.PhysicalParameters.SteadyState.PhysicsResidual));
put(fid,'States and physical inputs are divided by 48, and time is normalized by $t_0=10^{-3}$ s. This common scaling of the two local states preserves the scalar-block supply parametrization. Local supplies use $\mathcal X_i=[a_i I,\,\frac12 I;\,\frac12 I,\,-\rho I]$ with $a_i>0$. The global performance bound is from the additive normalized state disturbance to the normalized state error, rather than directly from primitive current/voltage noise.');
put(fid,latexFormat('The shared tuning grid is $\rho\in\{%s\}$; minimizing the worse certified gain of an accepted MB/DD pair selects $\rho=%.3g$. The global gain bound is 20, the common transformed communication budget is 10, and the normalized distance-weighted $\ell_1$ penalty is 0.02. Failed tuning attempts are retained with solver diagnostics.', ...
    strjoin(compose('%.3g',r.Options.RhoCandidates),','),r.SelectedRho));
put(fid,'\subsubsection{Data-driven experiment and scope}');
put(fid,'To avoid treating physical line currents as independent held inputs, the data-driven implementation uses an exact continuous-time integral regression. On each acquisition interval, let $X_i$ and $U_i$ contain the measured average state and average two-channel input, and let $\Delta_i$ contain the endpoint state difference divided by the normalized interval length. Then');
put(fid,'\begin{equation}\Delta_i=\widetilde A_i X_i+\widetilde B_i U_i+W_i.\label{Eq:IntegralDataRegression}\end{equation}');
put(fid,latexFormat('Each DG supplies %d transitions with a physical acquisition interval of $%.1g$ s. Converter commands are held on each interval, while the resistor network evolves continuously. A fixed local current-feedback gain of $-1$ is supplemented by independent uniform excitation of amplitude %.3g in normalized units. State and input measurements are noise-free. Primitive process disturbances are independently drawn in a box of Euclidean radius at most $d_{\max}=%.1g$ per DG.', ...
    r.Data.Options.Samples,r.Data.Options.SampleTime,r.Data.Options.Excitation,r.Data.Options.PrimitiveNoiseBound));
put(fid,latexFormat('Before generating the data, we declare $\|\widetilde B_i\|_2\leq %.3g$ and $W_iW_i^\top\preceq\eta I$, where $\eta=T(%.3g d_{\max})^2=%.3g$. This bound is not fitted to the realized residuals. All six input-state regression matrices have rank four, their data-consistency sets have strict interior, and independent checks confirm true-model membership and the integral data equation.', ...
    r.Data.Options.InputMatrixNormBound,r.Data.Options.InputMatrixNormBound,r.Data.Local{1}.EnergyBound));
put(fid,'The product of local data-consistency sets is used as a conservative outer approximation, without an independence assumption on physical line-current data. Positive QMI scaling and a fixed invertible congruence improve numerical conditioning. The continuous-time local data certificate is implemented as the following sufficient S-procedure. Define');
put(fid,'\begin{equation}N_i=\begin{bmatrix}\eta I-\Delta_i\Delta_i^\top&\Delta_i R_i^\top\\R_i\Delta_i^\top&-R_iR_i^\top\end{bmatrix},\qquad R_i=\begin{bmatrix}X_i\\U_i\end{bmatrix}.\end{equation}');
put(fid,'With $P_i\succ0$, $L_i=[0;\ell_i]$, and $\lambda_i\geq0$, the implementation enforces the hard LMI \eqref{Eq:IntegralLocalCertificate}.');
put(fid,'\begin{figure*}[t]\begin{equation}\begin{bmatrix}0&-P_i&-L_i^\top&\frac12P_i-I&P_i\\-P_i&0&0&0&0\\-L_i&0&0&0&0\\\frac12P_i-I&0&0&a_iI&0\\P_i&0&0&0&\rho^{-1}I\end{bmatrix}-\lambda_i\operatorname{diag}(N_i,0,0)\succeq0.\label{Eq:IntegralLocalCertificate}\end{equation}\hrulefill\end{figure*}');
put(fid,'Substitution of $[e_i;\widetilde A_i^\top e_i;\widetilde B_i^\top e_i;v_i;q_i]$, followed by a Schur complement and congruence, gives the original continuous-time local storage inequality for $K_i=L_iP_i^{-1}$ and storage $P_i^{-1}$. Thus this experiment implements a sufficient continuous-time integral-data counterpart; it does not use a forward-Euler approximation of the physical network.');
put(fid,'The data-driven local stage is followed by the hard model-based global composition LMI using the known input matrices and physical conductance network. Consequently, the DD results below are explicitly a local data-driven/known-input-matrix global design. They do not validate the general unknown-input-matrix global construction in Prop.~\ref{Pr:DataDrivenGlobalControllerDesign}, whose lifted LMI remains subject to the principal-block obstruction documented in the revision audit. No softened certificate is accepted. Every selected graph is imposed in a second solve, and the original local, global supply-dominance, and aggregate storage inequalities are checked independently after gain recovery.');
put(fid,'\subsubsection{Regenerated responses and quantitative comparison}');
put(fid,latexFormat(['As an external literature baseline, we implement the conventional decentralized voltage--current droop law $V_{ti}=V_{0i}-R_{di}I_{ti}$ used as a primary control layer in \cite{Guerrero2011HierarchicalDroop,Lu2014ImprovedDroop}. ', ...
    'The coefficients are fixed before simulation as $R_{di}=\delta_V V_{\mathrm{rated},i}/I_{\mathrm{rated},i}$ with $\delta_V=%.0f\%%$, giving $R_{di}\in[%.4f,%.4f]$ $\Omega$. ', ...
    'For a matched comparison, $V_{0i}=V_{Sti}+R_{di}I_{Eti}$ preserves the same verified equilibrium and feedforward command as the other methods. The controller uses only local converter current, has no communication links, and carries no dissipativity or robustness-certificate claim. It represents conventional primary droop, not the communication-based secondary restoration loops proposed in \cite{Lu2014ImprovedDroop}.'], ...
    100*droop.VoltageDroopFraction,min(droop.DroopResistance), ...
    max(droop.DroopResistance)));
put(fid,'Figure~\ref{Fig:DCMG-Comparison} regenerates the original large-initial-error comparison using freshly synthesized controllers. These are linear-model responses: command saturation and independent line-current clipping are disabled. The archived initial condition includes negative voltages and large current errors, so this plot is a mathematical reproduction benchmark rather than an operating-envelope validation.');
put(fid,'\begin{figure*}[t]\centering\includegraphics[width=0.99\textwidth]{Results/Regenerated/paper_trajectories.pdf}\caption{Fresh controller responses from the archived six-DG initial condition. Columns use the stabilizing MB, hierarchical MB, integral-data local/known-$B$ global, and conventional droop controllers.}\label{Fig:DCMG-Comparison}\end{figure*}');
put(fid,'\begin{figure*}[t]\centering\includegraphics[width=0.96\textwidth]{Results/Regenerated/paper_topologies.pdf}\caption{Regenerated topologies. Gray solid edges are the seven physical resistive lines; orange dashed arrows are directed communication links. Local self-feedback is excluded from the communication count.}\label{Fig:RegeneratedTopologies}\end{figure*}');
put(fid,latexFormat('The stabilizing design uses %d directed communication links. Both co-designs retain nonzero local and diagonal coordination feedback but require %d and %d off-diagonal links, respectively (Fig.~\ref{Fig:RegeneratedTopologies}). In this experiment the physical coupling and equilibrium feedforward allow the optimized feedback to be decentralized. This outcome supersedes the historical 15-link picture and should not be interpreted as a universal zero-communication result.',s.DirectedLinks(1),s.DirectedLinks(2),s.DirectedLinks(3)));
put(fid,'For the quantitative nominal comparison, initial voltage/current offsets are $\pm1.5$ V and $\pm0.35$ A with a fixed sign pattern. Settling time is the last-entry time into two percent of the initial normalized state-error norm. A separate, matched disturbance experiment starts at equilibrium, applies a fixed-sign current/command disturbance pulse of amplitudes 0.35 A and 0.5 V on 25--35 ms, and applies a symmetric state jump at 65 ms. The voltage and sharing RMS metrics in Table~\ref{Tab:RegeneratedMetrics} are evaluated over this complete 120 ms disturbance run.');
put(fid,'\begin{table*}[t]\centering\caption{Recomputed metrics. The certified $\gamma$ uses normalized additive state disturbances. A dash denotes a non-certified comparison controller.}\label{Tab:RegeneratedMetrics}\begin{tabular}{lrrrrrr}\hline Method & Directed links & $\gamma$ & Max. Re pole & Settling (ms) & Voltage RMS (V) & Sharing RMS (p.u.)\\\hline');
names=cellstr(r.Methods);
names{3}='DD local / known-$B$ global';
names{droopIndex}=strrep(names{droopIndex},'%','\%');
for k=1:numel(names)
    if isnan(s.Gamma(k)), g='--'; else, g=latexFormat('%.4f',s.Gamma(k)); end
    put(fid,latexFormat('%s & %d & %s & %.2f & %.2f & %.4f & %.5f \\', ...
        names{k},s.DirectedLinks(k),g,s.MaxRealPole(k),s.SettlingMs(k), ...
        s.DisturbanceVoltageRMS(k),s.DisturbanceSharingRMS(k)));
end
put(fid,'\hline\end{tabular}\end{table*}');
put(fid,latexFormat(['On this fixed linear ZI benchmark, the %.0f\%% droop baseline has a %.2f-ms nominal settling time, %.4f-V disturbance voltage RMS error, %.5f-p.u. sharing RMS error, and %.4f-V peak command deviation. ', ...
    'The corresponding DD local/known-$B$ global values are %.2f ms, %.4f V, %.5f p.u., and %.4f V. These numbers show the measured tradeoff rather than uniform dominance: the proposed method is assessed jointly on dynamic error, effort, communication, and its independently checked certificate, whereas primary droop is a zero-communication empirical baseline.'], ...
    100*droop.VoltageDroopFraction,s.SettlingMs(droopIndex),s.DisturbanceVoltageRMS(droopIndex), ...
    s.DisturbanceSharingRMS(droopIndex),s.PeakCommandDeviation(droopIndex), ...
    s.SettlingMs(3),s.DisturbanceVoltageRMS(3), ...
    s.DisturbanceSharingRMS(3),s.PeakCommandDeviation(3)));
ds=r.DroopSensitivity.Table;
put(fid,latexFormat(['A declared sensitivity sweep over $\delta_V\in\{%s\}\%%$ was run without selecting a coefficient from the outcomes. Across that grid, voltage RMS error ranges from %.4f to %.4f V and sharing RMS error ranges from %.5f to %.5f p.u.; the full table is saved as \texttt{droop\_sensitivity.csv}.'], ...
    strjoin(compose('%g',ds.DroopPercent),','), ...
    min(ds.DisturbanceVoltageRMS),max(ds.DisturbanceVoltageRMS), ...
    min(ds.DisturbanceSharingRMS),max(ds.DisturbanceSharingRMS)));
put(fid,latexFormat('The MB and DD aggregate storage-residual minimum eigenvalues are $%.3e$ and $%.3e$, respectively; the minimum original local residual eigenvalues are $%.3e$ and $%.3e$. The known physical-row equalities have residuals below $%.1e$. These diagnostics accompany the unrounded gains and decision matrices in the saved result record.', ...
    mb.AggregateVerification.MinEigenvalue,dd.AggregateVerification.MinEigenvalue, ...
    s.OriginalLocalMinEig(2),s.OriginalLocalMinEig(3),max(mb.PhysicalResidual,dd.PhysicalResidual)+eps));
put(fid,'\begin{figure*}[t]\centering\includegraphics[width=0.86\textwidth]{Results/Regenerated/paper_comparison.pdf}\caption{Nominal recovery and matched disturbance responses. Both voltage tracking and proportional-current-sharing errors are reported, together with controller effort.}\label{Fig:RegeneratedComparison}\end{figure*}');
if isfield(r,'Variation')
    put(fid,'A separate stress experiment varies $L_i,C_i,R_{fi},R_{Li}$ and the constant-current load independently within $\pm10\%$, using a fixed saved seed. Frozen gains are compared with offline MB and DD redesigns on the changed plant (Fig.~\ref{Fig:RegeneratedVariation}). The equilibrium is recomputed for both methods. The DD redesign uses newly collected data and updated known input matrices. This is an empirical parameter-variation study, not a polytopic robustness certificate or an online-adaptation demonstration.');
    put(fid,'\begin{figure*}[t]\centering\includegraphics[width=0.86\textwidth]{Results/Regenerated/paper_variation.pdf}\caption{Declared physical-parameter stress experiment, comparing frozen gains and independently verified offline redesigns.}\label{Fig:RegeneratedVariation}\end{figure*}');
end
put(fid,latexFormat('The complete experiment, including both literature baselines and regression checks, is regenerated by \texttt{run\_all\_paper\_results.m} (also called by \texttt{main.mlx}). The saved records include component values, seeds, data bounds, all tuning attempts, gains, certificates, trajectories, source hashes, and metrics. This run used MATLAB %s, YALMIP %s, and %s. Exact propagation agrees with the existing \texttt{DCMicrogrid.dynamics} ODE simulation to $%.2e$ in the state infinity norm over the regression interval.', ...
    r.MatlabVersion,r.YalmipVersion,upper(r.Solver),max(r.ImplementationChecks.ODEResidual)));
clear c
fid=fopen(fullfile(outdir,'RESULTS_SUMMARY.md'),'w');
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
put(fid,'# Regenerated MATLAB results');
put(fid,['Scope: ',r.Scope]);
put(fid,'Run `report = run_all_paper_results` for the complete comparison and checks; `run_paper_results` rebuilds this core record alone.');
put(fid,'');
put(fid,'| Method | Directed links | Certified gamma | Settling (ms) | Max real pole |');
put(fid,'|---|---:|---:|---:|---:|');
for k=1:numel(r.Methods)
    put(fid,latexFormat('| %s | %d | %.5g | %.3g | %.5g |',r.Methods(k), ...
        s.DirectedLinks(k),s.Gamma(k),s.SettlingMs(k),s.MaxRealPole(k)));
end
put(fid,'');
put(fid,'The general unknown-B global theorem is not validated by this implementation. Integral-data local synthesis is a sufficient continuous-time counterpart. Model-based and data-driven co-designs share the same plant, scaling, tuning grid, budget, and certificate gates.');
put(fid,'');
put(fid,'See `paper_results.mat` for all raw data, unrounded gains and certificates; `metrics.csv` and `droop_sensitivity.csv` for metrics; `design_attempts.mat` for accepted and rejected attempts; `numerical_results.tex` for generated manuscript text; and `.fig`/`.pdf`/`.png` for figures.');
% Numerical SourceHashes identify the synthesis run. This separate manifest
% identifies final artifact-only formatting revisions without rerunning SDPs.
manifest=fopen(fullfile(outdir,'artifact_sources.sha256'),'w');
folder=fileparts(mfilename('fullpath'));
for name={'writePaperResultsText.m','plotPaperResults.m'}
    source=fopen(fullfile(folder,name{1}),'rb'); bytes=fread(source,Inf,'*uint8'); fclose(source);
    digest=java.security.MessageDigest.getInstance('SHA-256'); digest.update(bytes);
    hash=lower(reshape(dec2hex(typecast(digest.digest(),'uint8'),2)',1,[]));
    fprintf(manifest,'%s  support/%s\n',hash,name{1});
end
fclose(manifest);
end

function put(fid,line)
[tokens,matches]=regexp(line,'([0-9]+(?:\.[0-9]+)?)e([+-]?[0-9]+)','tokens','match');
for k=1:numel(tokens)
    line=strrep(line,matches{k},[tokens{k}{1},'\times 10^{', ...
        num2str(str2double(tokens{k}{2})),'}']);
end
fprintf(fid,'%s\n',line);
end

function text=latexFormat(format,varargin)
text=sprintf(strrep(format,'\','\\'),varargin{:});
end
